using System.Windows;using AutoPecasERP.Data.Context;using AutoPecasERP.Services.Relatorios;
namespace AutoPecasERP.Desktop.Views;
public partial class RelatoriosWindow:Window{readonly ErpDbContext _db=new();public RelatoriosWindow(){InitializeComponent();Loaded+=Carregar;}async void Carregar(object s,RoutedEventArgs e){var r=new RelatorioService(_db);var d=await r.DashboardAsync();FatHoje.Text=d.FaturamentoHoje.ToString("C");VendaMes.Text=d.VendasMes.ToString("C");Ticket.Text=d.TicketMedio.ToString("C");Receber.Text=d.ContasReceber.ToString("C");Baixo.Text=d.EstoqueBaixo.ToString();ClientesGrid.ItemsSource=await r.TopClientesAsync();ProdutosGrid.ItemsSource=await r.TopProdutosAsync();DiasGrid.ItemsSource=await r.VendasPorDiaAsync();Resumo.Text=$"Clientes ativos: {d.ClientesAtivos}\nProdutos cadastrados: {d.Produtos}\nProdutos em estoque baixo: {d.EstoqueBaixo}\nVendas perdidas registradas: {d.VendasPerdidas:C}\nOrdens de serviço abertas: {d.OsAbertas}";}}